// Worker entry: wraps the OpenNext handler to log one structured line per request with its
// outbound subrequest count, which Workers Logs does not report on its own. CPU and wall time come
// from the platform's own invocation logs.
import { tally, type SubrequestTally } from "./count-subrequests";
// Generated by `npm run cf:build`. This file is excluded from `tsc` because that import does not
// exist until a Workers build has run; Wrangler strips its types when bundling.
import handler from "../.open-next/worker.js";

type Context = { waitUntil(promise: Promise<unknown>): void };
type Handler = { fetch(request: Request, env: unknown, ctx: Context): Promise<Response> };

const worker = {
  async fetch(request: Request, env: unknown, ctx: Context): Promise<Response> {
    const store: SubrequestTally = { total: 0, hosts: {} };
    const response = await tally.run(store, () => (handler as Handler).fetch(request, env, ctx));
    const report = () => console.log(JSON.stringify({ subrequests: store.total, hosts: store.hosts, path: new URL(request.url).pathname, status: response.status }));
    if (!response.body) {
      report();
      return response;
    }
    // Server components keep fetching while the body streams, so count until the stream ends.
    const { readable, writable } = new TransformStream();
    ctx.waitUntil(response.body.pipeTo(writable).finally(report));
    return new Response(readable, response);
  },
};

export default worker;
